{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured, which could lead to unintended public exposure."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have access logging enabled, which makes it difficult to track access and detect potential unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle configuration, which could lead to unnecessary storage costs and inefficient data management."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"b\" {\n  bucket = \"my-tf-test-bucket-ggff\"\n  acl    = \"private\"\n\n  lifecycle_rule {\n    id      = \"expire-old-objects\"\n    enabled = true\n\n    expiration {\n      days = 365\n    }\n  }\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"b\" {\n  bucket                  = aws_s3_bucket.b.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_logging\" \"b\" {\n  bucket        = aws_s3_bucket.b.id\n  target_bucket = \"my-logging-bucket\"\n  target_prefix = \"log/\"\n}",
  "fix_summary": "Added a Public Access block to prevent unintended public exposure, enabled access logging for observability, and added a lifecycle rule to manage object expiration."
}
